var SG0='\u200B', SG1='\u200C', SGS='\u200D', SGE='\u2060';
function sgUtf8Encode(str){
  var out=[], i=0;
  while(i<str.length){
    var c=str.codePointAt(i);
    i+=c>0xFFFF?2:1;
    if(c<0x80) out.push(c);
    else if(c<0x800){ out.push(0xC0|(c>>6), 0x80|(c&63)); }
    else if(c<0x10000){ out.push(0xE0|(c>>12), 0x80|((c>>6)&63), 0x80|(c&63)); }
    else { out.push(0xF0|(c>>18), 0x80|((c>>12)&63), 0x80|((c>>6)&63), 0x80|(c&63)); }
  }
  return out;
}
function sgUtf8Decode(bytes){
  var s='', i=0;
  while(i<bytes.length){
    var b=bytes[i];
    if(b<0x80){ s+=String.fromCodePoint(b); i++; }
    else if((b&0xE0)===0xC0){
      if(i+1>=bytes.length) return null;
      s+=String.fromCodePoint(((b&31)<<6)|(bytes[i+1]&63)); i+=2;
    } else if((b&0xF0)===0xE0){
      if(i+2>=bytes.length) return null;
      s+=String.fromCodePoint(((b&15)<<12)|((bytes[i+1]&63)<<6)|(bytes[i+2]&63)); i+=3;
    } else if((b&0xF8)===0xF0){
      if(i+3>=bytes.length) return null;
      s+=String.fromCodePoint(((b&7)<<18)|((bytes[i+1]&63)<<12)|((bytes[i+2]&63)<<6)|(bytes[i+3]&63)); i+=4;
    } else return null;
  }
  return s;
}
function sgHide(cover, secret){
  if(typeof cover!=='string'||!cover.length) return { value:null, error:'载体文本为空' };
  if(typeof secret!=='string'||!secret.length) return { value:null, error:'秘密消息为空' };
  if(/[\u200B\u200C\u200D\u2060]/.test(cover)) return { value:null, error:'载体已含零宽字符（可能已有隐写）' };
  var bytes=sgUtf8Encode(secret), bits='';
  for(var i=0;i<bytes.length;i++){
    var b=bytes[i].toString(2);
    while(b.length<8) b='0'+b;
    bits+=b;
  }
  var payload=SGS;
  for(var j=0;j<bits.length;j++) payload+=bits.charAt(j)==='0'?SG0:SG1;
  payload+=SGE;
  var cut=Math.min(1, cover.length);
  return { value:cover.slice(0,cut)+payload+cover.slice(cut), error:null };
}
function sgReveal(text){
  if(typeof text!=='string'||!text.length) return { value:null, error:'文本为空' };
  var s=text.indexOf(SGS), e=text.indexOf(SGE);
  if(s===-1||e===-1||e<s) return { value:null, error:'未发现隐写载荷（缺起止标记）' };
  var body=text.slice(s+1, e), bits='';
  for(var i=0;i<body.length;i++){
    var ch=body.charAt(i);
    if(ch===SG0) bits+='0';
    else if(ch===SG1) bits+='1';
    else return { value:null, error:'载荷中混入非法字符' };
  }
  if(!bits.length||bits.length%8!==0) return { value:null, error:'载荷位数不是 8 的倍数（已损坏）' };
  var bytes=[];
  for(var k=0;k<bits.length;k+=8) bytes.push(parseInt(bits.slice(k,k+8),2));
  var msg=sgUtf8Decode(bytes);
  if(msg===null) return { value:null, error:'UTF-8 解码失败（载荷损坏）' };
  return { value:msg, error:null };
}
function sgDetect(text){
  if(typeof text!=='string') return { zeroWidthCount:0, hasPayload:false, visibleLength:0 };
  var zw=(text.match(/[\u200B\u200C\u200D\u2060]/g)||[]).length;
  return {
    zeroWidthCount:zw,
    hasPayload:text.indexOf(SGS)!==-1 && text.indexOf(SGE)>text.indexOf(SGS),
    visibleLength:text.replace(/[\u200B\u200C\u200D\u2060]/g,'').length
  };
}
function sgStrip(text){
  return String(text).replace(/[\u200B\u200C\u200D\u2060]/g,'');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { sgHide:sgHide, sgReveal:sgReveal, sgDetect:sgDetect, sgStrip:sgStrip, sgUtf8Encode:sgUtf8Encode, sgUtf8Decode:sgUtf8Decode };
}
if (typeof window !== 'undefined') {
  window.StegForgePure = { sgHide:sgHide, sgReveal:sgReveal, sgDetect:sgDetect, sgStrip:sgStrip, sgUtf8Encode:sgUtf8Encode, sgUtf8Decode:sgUtf8Decode };
}
